import { useState } from "react";

function TableExample() {
  const [row1, setRow1] = useState(() => false);

  const [row2, setRow2] = useState(() => true);

  const [showEmpty, setShowEmpty] = useState(() => false);

  const [sortDir, setSortDir] = useState(() => "none");

  function toggleAll(checked) {
    setRow1(checked);
    setRow2(checked);
  }

  function updateRow1(checked) {
    setRow1(checked);
  }

  function updateRow2(checked) {
    setRow2(checked);
  }

  function cycleSort() {
    setSortDir(
      sortDir === "asc" ? "desc" : sortDir === "desc" ? "none" : "asc"
    );
  }

  return (
    <div className="flex w-full flex-col gap-3">
      <div className="flex items-center justify-end">
        <button
          type="button"
          className="rounded-md border border-border-default bg-background-default px-2.5 py-1 text-xs font-medium text-foreground-default hover:bg-background-muted"
          onClick={(event) => {
            setShowEmpty(!showEmpty);
          }}
        >
          {showEmpty ? <>Show Populated Rows</> : <>Preview Empty State</>}
        </button>
      </div>
      <Table caption="Customer orders">
        <thead>
          <TableHeaderRow>
            <TableCheckboxHeaderCell
              checked={row1 && row2}
              indeterminate={(row1 || row2) && !(row1 && row2)}
              onCheckedChange={(checked) => toggleAll(checked)}
            />
            <TableNoHeaderCell />
            <TableHeaderCell
              sortable
              sortDirection={sortDir}
              onSort={(event) => cycleSort()}
            >
              Customer
            </TableHeaderCell>
            <TableHeaderCell>Status</TableHeaderCell>
            <TableHeaderCell align="right">Amount</TableHeaderCell>
          </TableHeaderRow>
        </thead>
        <tbody>
          {!showEmpty ? (
            <>
              <TableBodyRow selected={row1}>
                <TableCheckboxBodyCell
                  checked={row1}
                  onCheckedChange={(checked) => updateRow1(checked)}
                />
                <TableNoBodyCell no={1} />
                <TableBodyCell>
                  <TableCellValue
                    layout="stacked"
                    secondaryText="john@komerce.id"
                  >
                    John Doe
                  </TableCellValue>
                </TableBodyCell>
                <TableBodyCell>
                  <TableCellValue status="success">Completed</TableCellValue>
                </TableBodyCell>
                <TableBodyCell align="right">
                  <TableCellValue align="right">$1,200.00</TableCellValue>
                </TableBodyCell>
              </TableBodyRow>
              <TableBodyRow selected={row2}>
                <TableCheckboxBodyCell
                  checked={row2}
                  onCheckedChange={(checked) => updateRow2(checked)}
                />
                <TableNoBodyCell no={2} />
                <TableBodyCell>
                  <TableCellValue
                    layout="stacked"
                    secondaryText="jane@komerce.id"
                  >
                    Jane Smith
                  </TableCellValue>
                </TableBodyCell>
                <TableBodyCell>
                  <TableCellValue status="warning">Pending</TableCellValue>
                </TableBodyCell>
                <TableBodyCell align="right">
                  <TableCellValue align="right">$850.00</TableCellValue>
                </TableBodyCell>
              </TableBodyRow>
            </>
          ) : null}
          {showEmpty ? (
            <TableEmpty
              title="No matching orders"
              description="Try adjusting your search or filter to find what you are looking for."
              ctaLabel="Reset Filters"
              colSpan={5}
              showCTA
              onCtaClick={(event) => {
                setShowEmpty(false);
              }}
            />
          ) : null}
        </tbody>
      </Table>
    </div>
  );
}

export default TableExample;
